# Phase 3I: run of the ANOM / ALT reproduction and verification on one canonical CSV against the frozen V1.4 reference files (read only). Aggregate output only; no participant-level value is written.

.siw_ah_not_run <- c("ANOM_REPRODUCTION_STATUS", "ANOM_VERIFICATION_STATUS", "ANOM_VERIFICATION_STATUS_V2", "ALT_REPRODUCTION_STATUS", "ALT_VERIFICATION_STATUS")

#' Run the anomaly (ANOM, 7,080) and alternative-history (ALT, 312) reproduction and verification against the frozen V1.4 reference files named in the declared protocol.
#' @param protocol_path optional alternative protocol (synthetic tests only); windows_subset / metrics_subset come from the protocol parameters
#' @export
siw_run_anomaly_history_validation <- function(data_csv, reference_dir, out_dir, config = siw_load_config(), protocol_path = NULL) {
  t0 <- proc.time()[["elapsed"]]; reference_dir <- normalizePath(reference_dir, winslash = "/", mustWork = TRUE); dir.create(out_dir, recursive = TRUE, showWarnings = FALSE); out_dir <- normalizePath(out_dir, winslash = "/")
  if (startsWith(out_dir, paste0(reference_dir, "/")) || startsWith(reference_dir, paste0(out_dir, "/"))) stop("SIW_AH_OUTPUT_AND_REFERENCE_FOLDERS_OVERLAP", call. = FALSE)
  options(sieccwinter.log_file = file.path(out_dir, "run.log")); on.exit(options(sieccwinter.log_file = NULL), add = TRUE)
  protocol <- siw_ah_protocol(protocol_path); P <- protocol$parameters; sm0 <- siw_source_manifest(); W <- function(x, f) siw_write_csv(x, file.path(out_dir, f)); siw_log("Phase 3I anomaly / alternative-history validation; protocol ", protocol$protocol_hash, "; source fingerprint ", sm0$fingerprint, " (", sm0$n_files, " files)")
  env <- .siw_v21_env(); jsonlite::write_json(env, file.path(out_dir, "anomhist_environment.json"), auto_unbox = TRUE, pretty = TRUE, null = "null"); writeLines(utils::capture.output(print(utils::sessionInfo())), file.path(out_dir, "anomhist_sessionInfo.txt"))
  comps <- c("ANOM", "ALT", "ANOMDIAG", "ALTPCA"); refs <- siw_daily_read_references(reference_dir, protocol, components = comps); W(refs$provenance, "anomhist_reference_provenance.csv")
  carried <- c(FINAL_NINE_L56_NUMERICAL_VALIDATION = "ACCEPTED_UNDER_V2_1 (not recomputed)", ARCHIVED_DLM_DETERMINISTIC = "ACCEPTED_PHASE3E1 (not recomputed)", COLD_BURDEN_NUMERICAL = "ACCEPTED_PHASE3F1 (not recomputed)", DAILY_LAYER_NUMERICAL = "ACCEPTED_PHASE3H1_H3 (not recomputed)", MANUSCRIPT_CONCORDANCE_STATUS = "REVIEW", FIGURE_PROVENANCE_STATUS = "NOT_TESTED", DLNM_EQUALITY_STATUS = "NOT_TESTED", J02_GLM_EPSILON_ENTRY_POINTS = "OPEN (no change made)")
  scope <- "SCOPE=exploratory families, separate from primary inference: ANOM 7,080 (windows 1-59 days, archived L01-L59) and ALT 312 (histories L01-L56); separate from the nine final L01-L56 models"
  finish <- function(st, status, extra = character(), msg = NULL) { writeLines(c(paste0(names(st), "=", st), extra, paste0(names(carried), "=", carried), scope, "Results were not altered, redrawn or replaced to fit any reference."), file.path(out_dir, "ANOMHIST_STATUS.txt"))
    sm1 <- siw_source_manifest(); W(sm0$manifest, "source_manifest_anomhist.csv"); writeLines(c(paste0("SOURCE_FINGERPRINT_SHA256=", sm0$fingerprint), paste0("FILES=", sm0$n_files), paste0("SOURCE_CHANGED_DURING_RUN=", !isTRUE(siw_source_manifest_diff(sm0, sm1)$identical_fingerprint))), file.path(out_dir, "SOURCE_FINGERPRINT.txt")); if (!is.null(msg)) writeLines(msg, file.path(out_dir, "RUN_SUMMARY.md")); list(out_dir = out_dir, statuses = st, status = status) }
  if (!refs$ok) { st <- c(EXECUTION_STATUS = "PASS", INPUT_PROVENANCE_STATUS = "FAIL", stats::setNames(rep("NOT_TESTED", length(.siw_ah_not_run)), .siw_ah_not_run), COVERAGE_STATUS = "FAIL", SOURCE_INTEGRITY_STATUS = "PASS"); bad <- refs$provenance[!refs$provenance$ok, ]
    fr <- finish(st, "VERIFICATION_FAILURE", c(paste0("PROVENANCE_PROBLEMS=", nrow(bad)), "NOTHING WAS COMPARED: required reference evidence is missing or does not match the declaration; nothing was passed."), c("# Anomaly / alternative-history validation: reference provenance FAILED", "", paste0("* Reference folder: `", reference_dir, "`"), paste0("* Problems: ", nrow(bad), " (see anomhist_reference_provenance.csv)"), "", "No comparison was made and nothing was passed.")); fr$provenance <- refs$provenance; return(fr) }
  ih <- siw_file_hash(data_csv); raw <- siw_read_study_csv(data_csv, config); rep <- siw_validate_input(raw, config, lag_end = P$lag_end); W(rep, "input_validation_report.csv"); if (any(rep$status == "FAIL")) stop("SIW_INPUT_VALIDATION_FAILED: see input_validation_report.csv", call. = FALSE)
  dat <- siw_prepare_data(raw, config); sec <- c(); tk <- function(nm, f) { a <- proc.time()[["elapsed"]]; v <- f(); sec[[nm]] <<- round(proc.time()[["elapsed"]] - a, 2); v }
  tolC <- config$tolerances; tolC$name <- "cumulative"; cmpC <- function(id) Filter(function(z) identical(z$id, id), protocol$comparisons)[[1L]]; wsub <- if (is.null(P$windows_subset)) NULL else as.integer(unlist(P$windows_subset)); msub <- if (is.null(P$metrics_subset)) NULL else as.character(unlist(P$metrics_subset))
  # ---- ANOM
  siw_log("ANOM: daily-reference anomaly scan (2 references x 8 metrics x methods x 2 burdens x 59 windows x 3 outcomes)"); sc <- tk("anom_scan", function() siw_anomaly_scan(dat, config, protocol, windows = wsub)); cA <- cmpC("ANOM_7080"); cG <- cmpC("ANOMDIAG_64"); kA <- unlist(cA$keys); kG <- unlist(cG$keys)
  rA <- tk("anom_compare", function() .siw_dl_cmp(cA, sc$results, refs$tables$ANOM, kA, tolC, "daily_anomaly_results.csv")); catA <- .siw_dl_cat(sc$results, refs$tables$ANOM, kA, c("model_id", unlist(cA$categorical)[unlist(cA$categorical) != "model_id"])); rG <- .siw_dl_cmp(cG, sc$diagnostics, refs$tables$ANOMDIAG, kG, tolC, "daily_anomaly_diagnostics.csv")
  W(rA$summary, "anom_comparison_summary.csv"); W(rA$detail, "anom_comparison_detail.csv"); W(catA, "anom_categorical_comparison.csv"); W(sc$results, "anom_package_results.csv"); W(rG$summary, "anomdiag_comparison_summary.csv"); W(rG$detail, "anomdiag_comparison_detail.csv"); W(sc$diagnostics, "anom_diagnostics_package.csv")
  siw_log("ANOM: independent verification"); va <- siw_anomaly_values(dat, config, protocol, "all"); vl <- siw_anomaly_values(dat, config, protocol, "locality")
  vV <- tk("anom_verify_values", function() rbind(siw_anomaly_values_verify(dat, config, protocol, va), siw_anomaly_values_verify(dat, config, protocol, vl))); W(vV, "anom_independent_anomaly_check.csv")
  vF <- tk("anom_verify_features", function() siw_anomaly_features_verify(config, protocol, va, vl, windows = wsub)); W(vF, "anom_feature_verification.csv"); mA <- siw_anomaly_multiplicity_verify(sc$results); W(mA, "anom_multiplicity_verification.csv")
  idA <- .siw_dl_identities(sc$results); idA$source <- "package"; idR <- .siw_dl_identities(refs$tables$ANOM[refs$tables$ANOM$status == "COMPLETED", ]); idR$source <- "frozen"; W(rbind(idA, idR), "anom_scale_and_inference_identities.csv")
  # protocol v2 (post hoc, 12 Oct 2026): per-row implied SD against the traced direct SD of the row's own complete-case sample; the v1 file above stays as it was
  p2 <- siw_ah_protocol_v2(v1_hash = protocol$protocol_hash, strict = is.null(protocol_path)); frz <- refs$tables$ANOM[refs$tables$ANOM$status == "COMPLETED", ]
  tr2 <- tk("anom_identity_v2_masks", function() siw_anom_traced_sd(dat, config, protocol, rbind(sc$results[SIW_AH_V2_KEYS], frz[SIW_AH_V2_KEYS])))
  v2A <- siw_anom_identity_v2(sc$results, tr2); v2R <- siw_anom_identity_v2(frz, tr2)
  W(rbind(cbind(source = "package", v2A$rows, stringsAsFactors = FALSE), cbind(source = "frozen", v2R$rows, stringsAsFactors = FALSE)), "anom_identity_v2_rows.csv")
  W(siw_anom_identities_v2_table(rbind(idA, idR), list(package = v2A$checks, frozen = v2R$checks)), "anom_scale_and_inference_identities_v2.csv")
  rf <- tk("anom_refit", function() siw_anomaly_refit_verify(dat, config, sc$results, sc$features, protocol, every = P$independent_refit_every_anom)); W(rf$summary, "anom_independent_refit_summary.csv"); W(rf$failures, "anom_independent_refit_failures.csv")
  W(data.frame(models_total = rf$models_total, models_independently_refitted = rf$models_refitted, every = rf$every, coverage = if (rf$every == 1L) "ALL MODELS" else paste0("SAMPLE: every ", rf$every, "th model"), stringsAsFactors = FALSE), "anom_refit_coverage.csv")
  # ---- ALT
  siw_log("ALT: alternative exposure-history methods"); al <- tk("alt_scan", function() siw_alt_scan(dat, config, protocol, metrics = msub)); cL <- cmpC("ALT_312"); cP <- cmpC("ALTPCA_439"); kL <- unlist(cL$keys); kP <- unlist(cP$keys)
  rL <- tk("alt_compare", function() .siw_dl_cmp(cL, al$results, refs$tables$ALT, kL, tolC, "alternative_method_results.csv")); rP <- .siw_dl_cmp(cP, al$pca_variance, refs$tables$ALTPCA, kP, tolC, "alternative_PCA_variance.csv")
  W(rL$summary, "alt_comparison_summary.csv"); W(rL$detail, "alt_comparison_detail.csv"); W(al$results, "alt_package_results.csv"); W(rP$summary, "altpca_comparison_summary.csv"); W(rP$detail, "altpca_comparison_detail.csv"); W(al$pca_variance, "alt_pca_variance_package.csv")
  sg <- siw_alt_pca_sign_diagnostic(al$results, refs$tables$ALT, tolC); W(sg, "alt_pca_sign_diagnostic.csv")
  siw_log("ALT: independent verification"); vAF <- tk("alt_verify_features", function() siw_alt_features_verify(config, protocol, al$features)); W(vAF, "alt_feature_verification.csv"); vAR <- tk("alt_verify_refit", function() siw_alt_refit_verify(dat, config, al$results, al$features, protocol)); W(vAR, "alt_refit_verification.csv")
  vAP <- siw_alt_pca_verify(config, protocol, al$features, al$pca_variance, tolC); W(vAP, "alt_pca_verification.csv"); mL <- siw_alt_multiplicity_verify(al$results); W(mL, "alt_multiplicity_verification.csv")
  W(data.frame(models_total = nrow(al$results), single_feature_models_refitted = sum(al$results$method != "three_disjoint_periods_joint"), joint_tests_recomputed = sum(al$results$method == "three_disjoint_periods_joint"), coverage = "ALL MODELS AND TESTS", stringsAsFactors = FALSE), "alt_refit_coverage.csv")
  # ---- statuses
  okc <- function(r, cc) grepl("^PASS", r$status) && isTRUE(r$n_compared == cc$expected_compared_cells); rs <- function(r) r$summary[1L, ]; nz <- function(x) if (!is.null(x) && nrow(x)) x else data.frame(status = character())
  st <- c(EXECUTION_STATUS = "PASS", INPUT_PROVENANCE_STATUS = "PASS", ANOM_REPRODUCTION_STATUS = if (okc(rs(rA), cA) && okc(rs(rG), cG) && all(catA$n_different == 0L)) "PASS" else "FAIL",
          ANOM_VERIFICATION_STATUS = .siw_dl_status(c(vV$status, vF$status, mA$status[mA$status != "INFO"], idA$status, idR$status, rf$summary$status)),
          ANOM_VERIFICATION_STATUS_V2 = .siw_dl_status(c(vV$status, vF$status, mA$status[mA$status != "INFO"], idA$status[idA$check != SIW_AH_V1_IDENTITY_CHECK], idR$status[idR$check != SIW_AH_V1_IDENTITY_CHECK], v2A$checks$status, v2R$checks$status, rf$summary$status)), ALT_REPRODUCTION_STATUS = if (okc(rs(rL), cL) && okc(rs(rP), cP)) "PASS" else "FAIL",
          ALT_VERIFICATION_STATUS = .siw_dl_status(c(vAF$status, vAR$status, vAP$status, mL$status[mL$status != "INFO"])))
  cov <- rbind(rs(rA), rs(rG), rs(rL), rs(rP)); decl <- c(cA$expected_compared_cells, cG$expected_compared_cells, cL$expected_compared_cells, cP$expected_compared_cells); cov$expected_compared_cells <- decl; cov$cells_as_declared <- cov$n_compared == cov$expected_compared_cells
  W(cov[, c("reference", "expected_records", "n_records_reference", "n_records_results", "expected_compared_cells", "n_compared", "n_exact", "n_within_tolerance", "n_different", "n_nonfinite", "n_unmatched", "n_duplicate", "n_missing_required", "n_unclassified", "cells_as_declared", "status", "reason")], "anomhist_comparison_coverage.csv")
  st[["COVERAGE_STATUS"]] <- if (all(cov$n_unclassified == 0L) && all(cov$cells_as_declared) && all(cov$n_records_reference == cov$expected_records) && all(cov$n_records_results == cov$n_records_reference)) "PASS" else "FAIL"
  sm1 <- siw_source_manifest(); st[["SOURCE_INTEGRITY_STATUS"]] <- if (!isTRUE(siw_source_manifest_diff(sm0, sm1)$identical_fingerprint)) "FAIL" else "PASS"
  gov <- st[names(st) != "ANOM_VERIFICATION_STATUS"]; overall <- if (any(gov != "PASS")) "VERIFICATION_FAILURE" else "OK"          # protocol v2 governs; the v1 composition is shown, superseded, for the record
  cl <- function(r, lab, cc) paste0(lab, "_CELLS=", r$n_compared, " (declared ", cc$expected_compared_cells, "); EXACT ", r$n_exact, "; WITHIN_TOLERANCE ", r$n_within_tolerance, "; DIFFERENT ", r$n_different)
  info <- c(cl(cov[1, ], "ANOM", cA), cl(cov[2, ], "ANOMDIAG", cG), cl(cov[3, ], "ALT", cL), cl(cov[4, ], "ALTPCA", cP), paste0("ANOM_REFIT_COVERAGE=", rf$models_refitted, " of ", rf$models_total, " models independently refitted (every ", rf$every, ")"), paste0("ALT_PCA_SIGN_DIFFERENCES=", sum(!sg$sign_equal, na.rm = TRUE), " of ", nrow(sg), " PC rows"),
    paste0("ANOM_VERIFICATION_GOVERNED_BY=ANOM_VERIFICATION_STATUS_V2 (protocol v2 ", p2$protocol_hash, ", post hoc, author decision 12 Oct 2026; extends v1 ", p2$extends_check, "); ANOM_VERIFICATION_STATUS is the v1 composition, superseded, kept for the record"),
    paste0("ANOM_IDENTITY_V1_BY_N=", .siw_dl_status(c(idA$status[idA$check == SIW_AH_V1_IDENTITY_CHECK], idR$status[idR$check == SIW_AH_V1_IDENTITY_CHECK])), " (V1 identity, superseded, kept for the record)"),
    paste0("ANOM_IDENTITY_V2_ROWS=package ", nrow(v2A$rows), ", frozen ", nrow(v2R$rows), "; max relative difference ", format(suppressWarnings(max(c(v2A$checks$max_rel_diff[3L], v2R$checks$max_rel_diff[3L]), na.rm = TRUE)), digits = 3), " (tolerance 1e-9); rows without a traced mask ", sum(!v2A$rows$mask_found) + sum(!v2R$rows$mask_found)), paste0("RUNTIME_SECONDS=", paste(names(sec), sec, sep = ":", collapse = " "), "; TOTAL ", round(proc.time()[["elapsed"]] - t0, 1)))
  jsonlite::write_json(list(package_version = siw_pkg_version(), batch = "3I_anomaly_and_history", protocol_hash = protocol$protocol_hash, protocol_v2_hash = p2$protocol_hash, protocol_v2_extends_check = p2$extends_check, config_hash = config$config_hash, input_hash = ih$value, source_fingerprint_sha256 = sm0$fingerprint, source_files = sm0$n_files, reference_hashes = vapply(protocol$reference_files, function(z) z$sha256, ""), statuses = as.list(st), seconds = as.list(sec), created_utc = format(Sys.time(), tz = "UTC", usetz = TRUE)), file.path(out_dir, "anomhist_metadata.json"), auto_unbox = TRUE, pretty = TRUE, null = "null")
  fin <- finish(st, overall, info, c("# Exploratory anomaly (ANOM 7,080) and alternative-history (ALT 312) families: reproduction and verification", "", paste0("* Protocol `", protocol$protocol_hash, "`; source fingerprint `", sm0$fingerprint, "` (", sm0$n_files, " files)"), "* Exploratory families, kept separate from primary inference; numerical reproduction and mathematical verification only; no scientific interpretation.", "", "## Statuses", "", paste0("* ", names(st), ": ", st), "", "## Counts and runtime", "", paste0("* ", info), "", "Nothing in this folder contains participant-level values."))
  fin$anom <- sc$results; fin$alt <- al$results; fin$coverage <- cov; fin$provenance <- refs$provenance; fin$seconds <- sec; fin$summ <- list(anom = rA$summary, anomdiag = rG$summary, alt = rL$summary, altpca = rP$summary); fin$cat <- list(anom = catA); fin$verify <- list(values = vV, features = vF, refit = rf, alt_features = vAF, alt_refit = vAR, alt_pca = vAP); fin$sign <- sg; fin
}
